<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\AdminActivityLog; use App\Models\ModerationScan; use App\Models\Violation; use App\Services\NotificationService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ModerationController extends Controller { public function index(Request $r){$scans=ModerationScan::with(['product','image','seller','store'])->when($r->status,fn($q,$s)=>$q->where('status',$s))->latest()->paginate(20)->withQueryString();return view('admin.moderation.index',compact('scans'));} public function show(ModerationScan $scan){$scan->load(['product.images','image','seller.violations','store.violations','reviewer']);return view('admin.moderation.show',compact('scan'));} public function review(Request $r,ModerationScan $scan){$data=$r->validate(['decision'=>['required','in:approved,rejected,false_positive,escalated'],'notes'=>['required','string','max:1500']]);DB::transaction(function()use($r,$scan,$data){$scan->update(['status'=>$data['decision']==='escalated'?'under_review':$data['decision'],'decision'=>$data['decision'],'review_notes'=>$data['notes'],'reviewed_by'=>$r->user()->id,'reviewed_at'=>now()]);if(in_array($data['decision'],['approved','false_positive']))$scan->product->update(['moderation_status'=>'approved','is_active'=>$scan->store?->status==='active']);elseif($data['decision']==='rejected'){$scan->product->update(['moderation_status'=>'rejected','is_active'=>false,'suspension_reason'=>$data['notes']]);Violation::create(['seller_id'=>$scan->seller_id,'store_id'=>$scan->store_id,'product_id'=>$scan->product_id,'moderation_scan_id'=>$scan->id,'recorded_by'=>$r->user()->id,'category'=>$scan->detected_category??'other','severity'=>$scan->risk_level,'description'=>$data['notes'],'action_taken'=>'product_rejected']);}if($scan->seller_id)NotificationService::send($scan->seller_id,$data['decision']==='rejected'?'Product not approved':'Product moderation completed',$data['notes'],'moderation',route('seller.products.index'));AdminActivityLog::record('moderation.'.$data['decision'],'moderation_scan',$scan->id,['notes'=>$data['notes']]);});return back()->with('success','Moderation decision saved.');} }
